<template>
  <section class="qag-space qag-profile"><router-link class="qag-back" to="/agent"><ClientIcon name="chevronLeft" />回到行动搭档馆</router-link><div v-if="loading" class="qag-detail-loading" role="status"><BrandLoader text="正在打开搭档的专长档案…" :size="50" /></div><div v-else-if="error" class="qag-empty" role="alert"><span>☁</span><h1>这位搭档，暂时不在场。</h1><p>{{ error }}</p><button class="qag-primary" type="button" @click="load">重新查看<ClientIcon name="refresh" /></button></div><template v-else-if="agent"><header class="qag-detail-hero"><div><span class="qag-eyebrow">QGAUSS / MEET YOUR ACTION PARTNER</span><span class="qag-ready" :class="{'is-ready':agent.ready}"><i></i>{{ agentAvailability(agent) }}</span><h1>{{ agent.name }}</h1><p>{{ agent.description||'让一位专业搭档，加入你的下一步。' }}</p><div class="qag-tags"><span v-for="tag in agent.tags||[]" :key="tag">{{ tag }}</span></div><div class="qag-detail-actions"><button class="qag-primary" type="button" :disabled="!agent.ready" @click="launch">{{ agent.ready?'开启协作会话':'连接准备好后再开始' }}<ClientIcon name="arrowUpRight" /></button><button class="qag-secondary" type="button" :aria-pressed="!!agent.favorited" :disabled="favoriteBusy" @click="favorite">{{ agent.favorited?'♥ 已收藏':'♡ 收藏搭档' }}</button></div><small class="qag-start-note">先打开新会话，由你发送第一个问题。</small></div><div class="qag-detail-sculpture" aria-hidden="true"><i></i><span>Q<small>YOUR NEXT<br>GOOD COMPANY</small></span><b>✦</b><em>✧</em></div></header><div class="qag-detail-grid"><section class="qag-detail-card"><span class="qag-eyebrow">A LITTLE HELLO</span><h2>从一句问候开始。</h2><blockquote>{{ agent.greeting||'你好，很高兴加入你的行动小队。今天，想一起完成什么？' }}</blockquote><small v-if="!agent.greeting">开场白示意 · 尚未设置专属问候</small><div v-if="agent.suggestedQuestions?.length" class="qag-detail-questions"><h3>也可以从这些问题开始</h3><button v-for="question in agent.suggestedQuestions" :key="question" type="button" :disabled="!agent.ready" @click="launch(question)">{{ question }}<ClientIcon name="arrowUpRight" /></button><small>点击打开会话并填入草稿，不自动发送。</small></div></section><aside class="qag-detail-card"><span class="qag-eyebrow">BEFORE WE BEGIN</span><h2>开始前，清楚一点。</h2><dl><div><dt>本轮报价</dt><dd>{{ agentQuote(agent).label }}</dd></div><div><dt>结算方式</dt><dd>{{ agentQuote(agent).detail }}</dd></div><div><dt>内容与附件</dt><dd>发送的问题和所选附件会交给配置的智能体服务处理。</dd></div><div><dt>协作方式</dt><dd>知识、工具和具体能力由搭档配置决定；支持的文件与任务仍需以实际返回为准。</dd></div></dl><p>停止时会向服务方提出取消请求；服务方可能仍产生计算或用量。</p></aside></div></template></section>
</template>
<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage} from 'element-plus';
import {api} from '../api/client.js';
import {useAuth} from '../stores/auth.js';
import {agentQuote,agentAvailability} from '../lib/agent-presentation.js';
import ClientIcon from '../components/reference/ClientIcon.vue';
import BrandLoader from '../components/design/BrandLoader.vue';
import '../components/design/agent-space.css';
const route=useRoute(),router=useRouter(),auth=useAuth(),agent=ref(null),loading=ref(true),error=ref(''),favoriteBusy=ref(false),id=computed(()=>String(route.query.agent||''));let active=true,controller=null,favoriteController=null,revision=0;
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal,version=++revision,identity=auth.identityRevision;agent.value=null;loading.value=true;error.value='';if(!id.value||id.value.length>200){error.value='没有找到对应的搭档，请回到列表重新选择。';loading.value=false;return;}try{const value=await api.get('/agents/'+encodeURIComponent(id.value),{signal});if(active&&!signal.aborted&&identity===auth.identityRevision&&version===revision)agent.value=value;}catch(e){if(active&&!signal.aborted&&identity===auth.identityRevision&&version===revision)error.value=e.status===404?'这位搭档可能已经下架，可以回到列表认识其他搭档。':e.message||'暂未打开档案，请重试。';}finally{if(active&&!signal.aborted&&version===revision)loading.value=false;}}
async function favorite(){if(!agent.value||favoriteBusy.value)return;const target=agent.value,identity=auth.identityRevision,c=new AbortController();favoriteController=c;favoriteBusy.value=true;try{const result=await api.post('/agents/'+encodeURIComponent(target.id)+'/favorite',{favorited:!target.favorited},{signal:c.signal});if(active&&!c.signal.aborted&&identity===auth.identityRevision&&agent.value===target)target.favorited=!!result.favorited;}catch(e){if(active&&!c.signal.aborted&&identity===auth.identityRevision)ElMessage.error(e.message||'收藏结果暂未确认，请刷新核对。');}finally{if(favoriteController===c){favoriteBusy.value=false;favoriteController=null;}}}
function launch(question){if(!agent.value?.ready)return;return router.push({path:'/agent/chat',query:{agent:agent.value.id,...(typeof question==='string'?{draft:question}:{})}});}
watch(id,()=>{favoriteController?.abort();favoriteBusy.value=false;void load();});watch(()=>auth.identityRevision,()=>{controller?.abort();favoriteController?.abort();agent.value=null;favoriteBusy.value=false;revision++;if(auth.isLoggedIn)void load();});onMounted(()=>{if(auth.isLoggedIn)void load();else loading.value=false;});onBeforeUnmount(()=>{active=false;controller?.abort();favoriteController?.abort();});
</script>
